describe('Conflict Error Message on Stale Record Save', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should display conflict error message when saving a stale record', () => {
    // Intercept the initial GET request
    cy.intercept('GET', '/api/records/123').as('getRecord');
    cy.wait('@getRecord');

    // Fill in the form with initial data
    cy.get('[data-testid="record-title-input"]').type('Initial Record Title');
    cy.get('[data-testid="record-description-input"]').type('This is the initial description.');

    // Intercept the PUT request with conflict response
    cy.intercept('PUT', '/api/records/123', {
      statusCode: 429,
      body: {
        error: 'Conflict',
        message: 'Record has been updated by another user. Please refresh and try again.',
        timestamp: new Date().toISOString()
      }
    }).as('updateRecordConflict');

    // Click save button
    cy.get('[data-testid="save-button"]').click();

    // Wait for the API call
    cy.wait('@updateRecordConflict');

    // Verify conflict error message is displayed
    cy.get('[data-testid="conflict-error-message"]')
      .should('be.visible')
      .should('contain', 'Record has been updated by another user');

    // Verify error styling
    cy.get('[data-testid="conflict-error-message"]')
      .should('have.class', 'error-text');

    // Verify form is not submitted
    cy.get('[data-testid="record-title-input"]').should('have.value', 'Initial Record Title');
  });

  it('should handle conflict error and allow user to refresh', () => {
    // Intercept the initial GET request
    cy.intercept('GET', '/api/records/123').as('getRecord');
    cy.wait('@getRecord');

    // Fill in the form
    cy.get('[data-testid="record-title-input"]').type('Another Record Title');
    cy.get('[data-testid="record-description-input"]').type('Another description.');

    // Intercept the PUT request with conflict response
    cy.intercept('PUT', '/api/records/123', {
      statusCode: 429,
      body: {
        error: 'Conflict',
        message: 'Record has been updated by another user. Please refresh and try again.',
        timestamp: new Date().toISOString()
      }
    }).as('updateRecordConflict');

    // Click save button
    cy.get('[data-testid="save-button"]').click();

    // Wait for the API call
    cy.wait('@updateRecordConflict');

    // Verify conflict error message is displayed
    cy.get('[data-testid="conflict-error-message"]')
      .should('be.visible')
      .should('contain', 'Record has been updated by another user');

    // Verify refresh button is visible
    cy.get('[data-testid="refresh-button"]')
      .should('be.visible')
      .should('contain', 'Refresh');

    // Click refresh button
    cy.get('[data-testid="refresh-button"]').click();

    // Verify form is cleared or reset
    cy.get('[data-testid="record-title-input"]').should('have.value', '');
    cy.get('[data-testid="record-description-input"]').should('have.value', '');
  });
});
